export function safeUrl(raw){try{const u=new URL(raw);return u.protocol==='https:'&&HOSTS.has(u.hostname)&&!u.username&&!u.password?u.href:null}catch{return null}}
export function routeCase(caseId,stateId,now=new Date()){
 if(!Object.hasOwn(CASES,caseId)||!Object.hasOwn(STATES,stateId))throw new Error('Selección no válida');
 const age=(now-new Date(REVIEWED+'T00:00:00Z'))/86400000;
 const stale=age>30;
 const c=CASES[caseId];
 return {...c,caseId,stateId,state:STATES[stateId],reviewed:REVIEWED,stale,steps:stale?['La fuente requiere una nueva revisión. Abre el sitio oficial para obtener orientación vigente.','No tomes esta tarjeta como confirmación del procedimiento actual.','Si hay un acto que no reconoces, busca orientación humana por los canales oficiales.']:c.steps};
}
